//! The part of the KB16 mixer firmware that touches no register and no Embassy type, so that
//! `cargo test` on the PC can run it. The firmware crate keeps the tasks, the drivers and the
//! register code, and calls into this crate for every decision and every pixel.

#![no_std]
#![forbid(unsafe_code)]

#[rustfmt::skip] // generated by firmware/gen_assets.py
pub mod assets;
pub mod boot;
pub mod flash;
#[rustfmt::skip] // generated by firmware/gen_assets.py
pub mod font;
pub mod input;
pub mod leds;
pub mod name;
pub mod oled;
pub mod state;

/// A point in time as the firmware clock gives it.
///
/// The firmware implements this for embassy-time's `Instant`. Tests and the screen renderer use
/// plain milliseconds (`u64`).
pub trait Time: Copy {
    /// Whole milliseconds since boot.
    fn ms(self) -> u64;
    /// Whole milliseconds from `earlier` to `self`; 0 if `earlier` is the later one.
    fn ms_since(self, earlier: Self) -> u64;
}

impl Time for u64 {
    fn ms(self) -> u64 {
        self
    }

    fn ms_since(self, earlier: u64) -> u64 {
        self.saturating_sub(earlier)
    }
}
